// Member of the node: tf2_ros::TransformBroadcaster broadcaster_{this};
void send(const bench::PlanarPose& odom_from_base, const rclcpp::Time& measured_at) {
  geometry_msgs::msg::TransformStamped t;
  t.header.stamp = measured_at;  // when the pose was true, not when it is sent
  t.header.frame_id = "odom";
  t.child_frame_id = "base_link";
  t.transform.translation.x = odom_from_base.x_m;
  t.transform.translation.y = odom_from_base.y_m;
  tf2::Quaternion q;
  q.setRPY(0.0, 0.0, odom_from_base.yaw_rad);
  t.transform.rotation = tf2::toMsg(q);
  broadcaster_.sendTransform(t);
}

#include <algorithm>
#include <iterator>
#include <memory>
#include <numbers>
#include <string>
#include <vector>

#include <geometry_msgs/msg/transform_stamped.hpp>
#include <rclcpp/rclcpp.hpp>
#include <tf2/LinearMath/Quaternion.hpp>
#include <tf2_geometry_msgs/tf2_geometry_msgs.hpp>
#include <tf2_ros/static_transform_broadcaster.hpp>

namespace bench {

// Where a part sits on the robot: metres, and roll, pitch and yaw in radians about the parent's fixed axes.
struct Mount {
  std::string parent;
  std::string child;
  double x = 0.0;
  double y = 0.0;
  double z = 0.0;
  double roll = 0.0;
  double pitch = 0.0;
  double yaw = 0.0;
};

[[nodiscard]] geometry_msgs::msg::TransformStamped to_message(const Mount& m, const rclcpp::Time& stamp) {
  geometry_msgs::msg::TransformStamped t;
  t.header.stamp = stamp;
  t.header.frame_id = m.parent;
  t.child_frame_id = m.child;
  t.transform.translation.x = m.x;
  t.transform.translation.y = m.y;
  t.transform.translation.z = m.z;
  tf2::Quaternion q;  // uninitialised until setRPY
  q.setRPY(m.roll, m.pitch, m.yaw);
  t.transform.rotation = tf2::toMsg(q);
  return t;
}

}  // namespace bench

class StaticFrames : public rclcpp::Node {
 public:
  explicit StaticFrames(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("static_frames", options), broadcaster_(this) {
    const std::vector<bench::Mount> mounts{
        {.parent = "base_link", .child = "bumper", .x = 0.20, .z = 0.05},
        {.parent = "base_link", .child = "rear_camera", .x = -0.15, .z = 0.30, .yaw = std::numbers::pi},
    };
    std::vector<geometry_msgs::msg::TransformStamped> transforms;
    std::ranges::transform(mounts, std::back_inserter(transforms),
                           [stamp = now()](const bench::Mount& m) { return bench::to_message(m, stamp); });
    broadcaster_.sendTransform(transforms);
    RCLCPP_INFO(get_logger(), "published %zu static transforms", transforms.size());
  }

 private:
  tf2_ros::StaticTransformBroadcaster broadcaster_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<StaticFrames>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cmath>
#include <memory>

#include <geometry_msgs/msg/transform.hpp>
#include <geometry_msgs/msg/transform_stamped.hpp>
#include <rclcpp/rclcpp.hpp>
#include <tf2/exceptions.hpp>
#include <tf2_ros/buffer.hpp>
#include <tf2_ros/transform_listener.hpp>

using namespace std::chrono_literals;

namespace bench {

struct PlanarPose {
  double x_m = 0.0;
  double y_m = 0.0;
  double yaw_rad = 0.0;
};

// The child's pose in the parent's plane: the yaw formula from the topic on rotations.
[[nodiscard]] PlanarPose planar(const geometry_msgs::msg::Transform& t) {
  const geometry_msgs::msg::Quaternion& q = t.rotation;
  return {.x_m = t.translation.x,
          .y_m = t.translation.y,
          .yaw_rad = std::atan2(2 * (q.w * q.z + q.x * q.y), 1 - 2 * (q.y * q.y + q.z * q.z))};
}

}  // namespace bench

class FrameWatch : public rclcpp::Node {
 public:
  explicit FrameWatch(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("frame_watch", options), buffer_(get_clock()), listener_(buffer_) {
    timer_ = create_timer(1s, [this] { report(); });
  }

 private:
  void report() {
    try {
      // Target "odom", source "base_link": the result converts base_link coordinates into odom.
      const geometry_msgs::msg::TransformStamped odom_from_base =
          buffer_.lookupTransform("odom", "base_link", tf2::TimePointZero);
      const bench::PlanarPose p = bench::planar(odom_from_base.transform);
      const double age_s = (now() - rclcpp::Time(odom_from_base.header.stamp)).seconds();
      RCLCPP_INFO(get_logger(), "base_link in odom: x %.3f m, y %.3f m, yaw %.3f rad, %.3f s old", p.x_m, p.y_m,
                  p.yaw_rad, age_s);
    } catch (const tf2::TransformException& e) {
      RCLCPP_WARN(get_logger(), "no odom -> base_link yet: %s", e.what());
    }
  }

  tf2_ros::Buffer buffer_;               // declared before the listener, which fills it
  tf2_ros::TransformListener listener_;  // subscribes to /tf and /tf_static on a thread of its own
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<FrameWatch>());
  rclcpp::shutdown();
}

#include <chrono>
#include <cmath>
#include <memory>
#include <string>

#include <geometry_msgs/msg/point_stamped.hpp>
#include <geometry_msgs/msg/transform_stamped.hpp>
#include <rclcpp/rclcpp.hpp>
#include <tf2/exceptions.hpp>
#include <tf2_geometry_msgs/tf2_geometry_msgs.hpp>
#include <tf2_ros/buffer.hpp>
#include <tf2_ros/transform_listener.hpp>

using namespace std::chrono_literals;

namespace bench {

struct Reading {
  double range_m = 0.0;
  double bearing_rad = 0.0;  // counterclockwise from the lidar's x axis
};

// A lidar return as a point in the lidar's frame. The stamp stays 0, which asks tf2 for the newest transform.
[[nodiscard]] geometry_msgs::msg::PointStamped to_point(const Reading& r, const std::string& lidar_frame) {
  geometry_msgs::msg::PointStamped p;
  p.header.frame_id = lidar_frame;
  p.point.x = r.range_m * std::cos(r.bearing_rad);
  p.point.y = r.range_m * std::sin(r.bearing_rad);
  return p;
}

}  // namespace bench

class LidarCheck : public rclcpp::Node {
 public:
  explicit LidarCheck(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
      : Node("lidar_check", options), buffer_(get_clock()), listener_(buffer_) {
    timer_ = create_timer(1s, [this] { report(); });
  }

 private:
  void report() {
    try {
      const geometry_msgs::msg::TransformStamped footprint_from_scan =
          buffer_.lookupTransform("base_footprint", "base_scan", tf2::TimePointZero);
      const geometry_msgs::msg::Vector3& mount = footprint_from_scan.transform.translation;
      RCLCPP_INFO(get_logger(), "base_scan in base_footprint: (%.3f, %.3f, %.3f)", mount.x, mount.y, mount.z);

      const geometry_msgs::msg::PointStamped ahead =
          buffer_.transform(bench::to_point({.range_m = 2.0}, "base_scan"), "base_footprint");
      RCLCPP_INFO(get_logger(), "2 m ahead of the lidar: (%.3f, %.3f, %.3f) in %s", ahead.point.x, ahead.point.y,
                  ahead.point.z, ahead.header.frame_id.c_str());
    } catch (const tf2::TransformException& e) {
      RCLCPP_WARN(get_logger(), "%s", e.what());
    }
  }

  tf2_ros::Buffer buffer_;
  tf2_ros::TransformListener listener_;
  rclcpp::TimerBase::SharedPtr timer_;
};

int main(int argc, char** argv) {
  rclcpp::init(argc, argv);
  rclcpp::spin(std::make_shared<LidarCheck>());
  rclcpp::shutdown();
}
